import{_ as o,a0 as n,w as r,s,ao as d,I as l,x as p,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"30個實例詳解TOP命令 | LCTT x X-CMD","titleTemplate":false,"description":"30個實例詳解TOP命令 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"30個實例詳解TOP命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"30個實例詳解TOP命令 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Unbelievable ! 30 Linux TOP Command Examples With Screenshots","title":"30個實例詳解TOP命令","tag":"201312","desc":""},"relativePath":"201312/Unbelievable ! 30 Linux TOP Command Examples With Screenshots.md","filePath":"[post].md"}'),h={name:"201312/Unbelievable ! 30 Linux TOP Command Examples With Screenshots.md"};function c(m,a,_,g,x,b){const e=n("Link");return r(),s("div",null,[a[11]||(a[11]=d(`<h1 id="_30個實例詳解top命令" tabindex="-1">30個實例詳解TOP命令 <a class="header-anchor" href="#_30個實例詳解top命令" aria-label="Permalink to “30個實例詳解TOP命令”">​</a></h1><p>Linux中的top命令顯示系統上正在運行的進程。它是系統管理員最重要的工具之一。被廣泛用於監視服務器的負載。在本篇中，我們會探索top命令的細節。top命令是一個交互命令。在運行top的時候還可以運行很多命令。我們也會探索這些命令。</p><p>（譯註：不同發行版的top命令在各種細節有不同，如果發現不同時，請讀你的幫助手冊和命令內的幫助。）</p><h2 id="_1-top-命令輸出" tabindex="-1">1. Top 命令輸出: <a class="header-anchor" href="#_1-top-命令輸出" aria-label="Permalink to “1. Top 命令輸出:”">​</a></h2><p>首先，讓我們瞭解一下輸出。top命令會顯示系統的很多信息。我們需要理解不同部分輸出的意義：默認運行時，top命令會顯示如下輸出：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/01.top_default.png" alt="默認顯示"></p><p>前幾行水平顯示了不同系統參數的概括，接下來是進程和它們在列中的屬性。</p><h3 id="_1-1-系統運行時間和平均負載" tabindex="-1">1.1 系統運行時間和平均負載： <a class="header-anchor" href="#_1-1-系統運行時間和平均負載" aria-label="Permalink to “1.1 系統運行時間和平均負載：”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/02.top_uptime.png" alt="顯示運行時間"></p><p>top命令的頂部顯示與uptime命令相似的輸出。</p><p>這些字段顯示：</p><ul><li>當前時間</li><li>系統已運行的時間</li><li>當前登錄用户的數量</li><li>相應最近5、10和15分鐘內的平均負載。</li></ul><p>可以使用&#39;l&#39;命令切換uptime的顯示。</p><h3 id="_1-2-任務" tabindex="-1">1.2 任務: <a class="header-anchor" href="#_1-2-任務" aria-label="Permalink to “1.2 任務:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/03.top_tasks.png" alt="任務概況"></p><p>第二行顯示的是任務或者進程的總結。進程可以處於不同的狀態。這裏顯示了全部進程的數量。除此之外，還有正在運行、睡眠、停止、殭屍進程的數量（殭屍是一種進程的狀態）。這些進程概括信息可以用&#39;t&#39;切換顯示。</p><h3 id="_1-3-cpu-狀態" tabindex="-1">1.3 CPU 狀態: <a class="header-anchor" href="#_1-3-cpu-狀態" aria-label="Permalink to “1.3 CPU 狀態:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/04.top_cpu_states.png" alt="CPU狀態顯示"></p><p>下一行顯示的是CPU狀態。 這裏顯示了不同模式下的所佔CPU時間的百分比。這些不同的CPU時間表示:</p><ul><li>us, user： 運行(未調整優先級的) 用户進程的CPU時間</li><li>sy，system: 運行內核進程的CPU時間</li><li>ni，niced：運行已調整優先級的用户進程的CPU時間</li><li>wa，IO wait: 用於等待IO完成的CPU時間</li><li>hi：處理硬件中斷的CPU時間</li><li>si: 處理軟件中斷的CPU時間</li><li>st：這個虛擬機被hypervisor偷去的CPU時間（譯註：如果當前處於一個hypervisor下的vm，實際上hypervisor也是要消耗一部分CPU處理時間的）。</li></ul><p>可以使用&#39;t&#39;命令切換顯示。</p><h3 id="_1-4-內存使用" tabindex="-1">1.4 內存使用: <a class="header-anchor" href="#_1-4-內存使用" aria-label="Permalink to “1.4 內存使用:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/05.top_mem_usage.png" alt="內存使用情況"></p><p>接下來兩行顯示內存使用率，有點像&#39;free&#39;命令。第一行是物理內存使用，第二行是虛擬內存使用(交換空間)。</p><p>物理內存顯示如下:全部可用內存、已使用內存、空閒內存、緩衝內存。相似地：交換部分顯示的是：全部、已使用、空閒和緩衝交換空間。</p><p>內存顯示可以用&#39;m&#39;命令切換。</p><h3 id="_1-5-字段-列" tabindex="-1">1.5 字段/列: <a class="header-anchor" href="#_1-5-字段-列" aria-label="Permalink to “1.5 字段/列:”">​</a></h3><p><img src="http://linoxide.com/wp-content/uploads/2013/11/06.top_fields.png" alt="任務信息列"></p><p>在橫向列出的系統屬性和狀態下面，是以列顯示的進程。不同的列代表下面要解釋的不同屬性。</p><p>默認上，top顯示這些關於進程的屬性：</p><p><strong>PID</strong></p><p>進程ID，進程的唯一標識符</p><p><strong>USER</strong></p><p>進程所有者的實際用户名。</p><p><strong>PR</strong></p><p>進程的調度優先級。這個字段的一些值是&#39;rt&#39;。這意味這這些進程運行在實時態。</p><p><strong>NI</strong></p><p>進程的nice值（優先級）。越小的值意味着越高的優先級。</p><p><strong>VIRT</strong></p><p>進程使用的虛擬內存。</p><p><strong>RES</strong></p><p>駐留內存大小。駐留內存是任務使用的非交換物理內存大小。</p><p><strong>SHR</strong></p><p>SHR是進程使用的共享內存。</p><p><strong>S</strong></p><p>這個是進程的狀態。它有以下不同的值:</p><ul><li>D - 不可中斷的睡眠態。</li><li>R – 運行態</li><li>S – 睡眠態</li><li>T – 被跟蹤或已停止</li><li>Z – 殭屍態</li></ul><p><strong>%CPU</strong></p><p>自從上一次更新時到現在任務所使用的CPU時間百分比。</p><p><strong>%MEM</strong></p><p>進程使用的可用物理內存百分比。</p><p><strong>TIME+</strong></p><p>任務啓動後到現在所使用的全部CPU時間，精確到百分之一秒。</p><p><strong>COMMAND</strong></p><p>運行進程所使用的命令。</p><p>還有許多在默認情況下不會顯示的輸出，它們可以顯示進程的頁錯誤、有效組和組ID和其他更多的信息。</p><h2 id="_2-交互命令" tabindex="-1">2. 交互命令: <a class="header-anchor" href="#_2-交互命令" aria-label="Permalink to “2. 交互命令:”">​</a></h2><p>我們之前説過top是一個交互命令。上一節我們已經遇到了一些命令。這裏我們會探索更多的命令。</p><h3 id="_2-1-h-幫助" tabindex="-1">2.1 ‘h’: 幫助 <a class="header-anchor" href="#_2-1-h-幫助" aria-label="Permalink to “2.1 ‘h’: 幫助”">​</a></h3><p>首先，我們可以用&#39;h&#39;或者&#39;?&#39;顯示交互命令的幫助菜單。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/07.top_help.png" alt="幫助菜單"></p><h3 id="_2-2-enter-或者-space-刷新顯示" tabindex="-1">2.2 ‘&lt;ENTER&gt;’ 或者 ‘&lt;SPACE&gt;’: 刷新顯示 <a class="header-anchor" href="#_2-2-enter-或者-space-刷新顯示" aria-label="Permalink to “2.2 ‘&lt;ENTER&gt;’ 或者 ‘&lt;SPACE&gt;’: 刷新顯示”">​</a></h3><p>top命令默認在一個特定間隔(3秒)後刷新顯示。要手動刷新，用户可以輸入回車或者空格。</p><h3 id="_2-3-a-切換交替顯示模式" tabindex="-1">2.3 ‘A’: 切換交替顯示模式 <a class="header-anchor" href="#_2-3-a-切換交替顯示模式" aria-label="Permalink to “2.3 ‘A’: 切換交替顯示模式”">​</a></h3><p>這個命令在全屏和交替模式間切換。在交替模式下會顯示4個窗口（譯註：分別關注不同的字段）:</p><ol><li>Def （默認字段組）</li><li>Job （任務字段組）</li><li>Mem （內存字段組）</li><li>Usr （用户字段組）</li></ol><p>這四組字段共有一個獨立的可配置的概括區域和它自己的可配置任務區域。4個窗口中只有一個窗口是當前窗口。當前窗口的名稱顯示在左上方。（譯註：只有當前窗口才會接受你鍵盤交互命令）</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/08.top_alternative_display.png" alt="交替顯示"></p><p>我們可以用&#39;a&#39;和&#39;w&#39;在4個 窗口間切換。&#39;a&#39;移到後一個窗口，&#39;w&#39;移到前一個窗口。用&#39;g&#39;命令你可以輸入一個數字來選擇當前窗口。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/09.top_alternate_window_selection.png" alt="在交替顯示中選擇窗口"></p><h3 id="_2-4-b-觸發粗體顯示" tabindex="-1">2.4 ‘B’: 觸發粗體顯示 <a class="header-anchor" href="#_2-4-b-觸發粗體顯示" aria-label="Permalink to “2.4 ‘B’: 觸發粗體顯示”">​</a></h3><p>一些重要信息會以加粗字體顯示。這個命令可以切換粗體顯示。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/10.top_bold_display_off.png" alt="關閉粗體"></p><h3 id="_2-5-d-或-s-設置顯示的刷新間隔" tabindex="-1">2.5 ‘d’ 或‘s’: 設置顯示的刷新間隔 <a class="header-anchor" href="#_2-5-d-或-s-設置顯示的刷新間隔" aria-label="Permalink to “2.5 ‘d’ 或‘s’: 設置顯示的刷新間隔”">​</a></h3><p>當按下&#39;d&#39;或&#39;s&#39;時，你將被提示輸入一個值（以秒為單位），它會以設置的值作為刷新間隔。如果你這裏輸入了1，top將會每秒刷新。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/11.top_display_time_interval.png" alt="刷新間隔l"></p><h3 id="_2-6-l-、-t-、-m-切換負載、任務、內存信息的顯示" tabindex="-1">2.6 ‘l’、‘t’、‘m’: 切換負載、任務、內存信息的顯示 <a class="header-anchor" href="#_2-6-l-、-t-、-m-切換負載、任務、內存信息的顯示" aria-label="Permalink to “2.6 ‘l’、‘t’、‘m’: 切換負載、任務、內存信息的顯示”">​</a></h3><p>這會相應地切換頂部的平均負載、任務/CPU狀態和內存信息的概況顯示。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/12.top_load_average_display_off.png" alt="不顯示平均負載"></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/13.top_cpu_display_off.png" alt="不顯示CPU概況"></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/14.top_mem_display_off.png" alt="不顯示內存和交換內存概況"></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/15.top_all_three_display_off.png" alt="上面三個全不顯示"></p><h3 id="_2-7-f-字段管理" tabindex="-1">2.7 ‘f’: 字段管理 <a class="header-anchor" href="#_2-7-f-字段管理" aria-label="Permalink to “2.7 ‘f’: 字段管理”">​</a></h3><p>用於選擇你想要顯示的字段。用&#39;*&#39;標記的是已選擇的。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/16.top_field_management.png" alt="管理顯示列"></p><p>上下光標鍵在字段內導航，左光標鍵可以選擇字段，回車或右光標鍵確認。</p><p>按&#39;&lt;&#39;移動已排序的字段到左邊，&#39;&gt;&#39;則移動到右邊。</p><h3 id="_2-8-r-反向排序" tabindex="-1">2.8 ‘R’: 反向排序 <a class="header-anchor" href="#_2-8-r-反向排序" aria-label="Permalink to “2.8 ‘R’: 反向排序”">​</a></h3><p>切換反向/常規排序。</p><h3 id="_2-9-c-觸發命令" tabindex="-1">2.9 ‘c’: 觸發命令 <a class="header-anchor" href="#_2-9-c-觸發命令" aria-label="Permalink to “2.9 ‘c’: 觸發命令”">​</a></h3><p>切換是否顯示進程啓動時的完整路徑和程序名。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/17.top_command_name_displayed.png" alt="完整命令路徑"></p><h3 id="_2-10-i-空閒任務" tabindex="-1">2.10 ‘i’: 空閒任務 <a class="header-anchor" href="#_2-10-i-空閒任務" aria-label="Permalink to “2.10 ‘i’: 空閒任務”">​</a></h3><p>切換顯示空閒任務。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/18.top_idle_tasks_off.png" alt="不顯示空閒命令"></p><h3 id="_2-11-v-樹視圖" tabindex="-1">2.11 ‘V’: 樹視圖 <a class="header-anchor" href="#_2-11-v-樹視圖" aria-label="Permalink to “2.11 ‘V’: 樹視圖”">​</a></h3><p>切換樹視圖。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/19.top_forest_view.png" alt="樹視圖"></p><h3 id="_2-12-z-改變配色" tabindex="-1">2.12 ‘Z’: 改變配色 <a class="header-anchor" href="#_2-12-z-改變配色" aria-label="Permalink to “2.12 ‘Z’: 改變配色”">​</a></h3><p>按下&#39;Z&#39;向用户顯示一個改變top命令的輸出顏色的屏幕。可以為8個任務區域選擇8種顏色。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/20.top_color_selection.png" alt="定製顏色"></p><p>下面顯示的是4中顏色顯示的top視圖。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/21.top_colored.png" alt="彩色顯示"></p><h3 id="_2-13-z-切換彩色顯示" tabindex="-1">2.13 ‘z’: 切換彩色顯示 <a class="header-anchor" href="#_2-13-z-切換彩色顯示" aria-label="Permalink to “2.13 ‘z’: 切換彩色顯示”">​</a></h3><p>切換彩色，即打開或關閉彩色顯示。</p><h3 id="_2-14-x-或者-y" tabindex="-1">2.14 ‘x’ 或者 ‘y’ <a class="header-anchor" href="#_2-14-x-或者-y" aria-label="Permalink to “2.14 ‘x’ 或者 ‘y’”">​</a></h3><p>切換高亮信息：&#39;x&#39;將排序字段高亮顯示（縱列）；&#39;y&#39;將運行進程高亮顯示（橫行）。依賴於你的顯示設置，你可能需要讓輸出彩色來看到這些高亮。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/22.top_x_y_displayed.png" alt="X 和 Y高亮"></p><h3 id="_2-15-u-特定用户的進程" tabindex="-1">2.15 ‘u’: 特定用户的進程 <a class="header-anchor" href="#_2-15-u-特定用户的進程" aria-label="Permalink to “2.15 ‘u’: 特定用户的進程”">​</a></h3><p>顯示特定用户的進程。你會被提示輸入用户名。空白將會顯示全部用户。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/23.top_raghu_processes.png" alt="raghu的進程"></p><h3 id="_2-16-n-或-任務的數量" tabindex="-1">2.16 ‘n’ 或 ‘#’: 任務的數量 <a class="header-anchor" href="#_2-16-n-或-任務的數量" aria-label="Permalink to “2.16 ‘n’ 或 ‘#’: 任務的數量”">​</a></h3><p>設置最大顯示的任務數量</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/24.top_10_processes.png" alt="設置最大顯示的任務數量"></p><h3 id="_2-17-k-結束任務" tabindex="-1">2.17 ‘k’: 結束任務 <a class="header-anchor" href="#_2-17-k-結束任務" aria-label="Permalink to “2.17 ‘k’: 結束任務”">​</a></h3><p>top命令中最重要的一個命令之一。用於發送信號給任務（通常是結束任務）。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/25.top_kill_task.png" alt="殺死一個任務"></p><h3 id="_2-18-r-重新設置優先級" tabindex="-1">2.18 ‘r’: 重新設置優先級 <a class="header-anchor" href="#_2-18-r-重新設置優先級" aria-label="Permalink to “2.18 ‘r’: 重新設置優先級”">​</a></h3><p>重新設置一個任務的調度優先級。</p><h2 id="_3-命令列選項" tabindex="-1">3. 命令列選項: <a class="header-anchor" href="#_3-命令列選項" aria-label="Permalink to “3. 命令列選項:”">​</a></h2><p>這些命令列選項與上面討論的命令大多相同。top的輸出可以用命令交互操作，但是你也可以帶參數運行top來設置你想要的效果。</p><h3 id="_3-1-b-批處理模式" tabindex="-1">3.1 -b: 批處理模式 <a class="header-anchor" href="#_3-1-b-批處理模式" aria-label="Permalink to “3.1 -b: 批處理模式”">​</a></h3><p>-b選項以批處理模式啓動top命令。當你想要在文件中保存輸出時是很有用的。</p><h3 id="_3-2-c-命令-程序名-觸發" tabindex="-1">3.2 -c: 命令/程序名 觸發: <a class="header-anchor" href="#_3-2-c-命令-程序名-觸發" aria-label="Permalink to “3.2 -c: 命令/程序名 觸發:”">​</a></h3><p>如上面所討論到的命令，這個選項會以上次記住的程序/命令顯示的狀態顯示（是否顯示完整路徑）。</p><h3 id="_3-3-d-設置延遲間隔" tabindex="-1">3.3 -d: 設置延遲間隔 <a class="header-anchor" href="#_3-3-d-設置延遲間隔" aria-label="Permalink to “3.3 -d: 設置延遲間隔”">​</a></h3><p>設置top的顯示間隔(以秒計)。比如。</p><pre><code>$ top -d 1 
</code></pre><p>將會以1秒的刷新間隔啓動top。</p><h3 id="_3-4-i-切換顯示空閒進程" tabindex="-1">3.4 -i: 切換顯示空閒進程 <a class="header-anchor" href="#_3-4-i-切換顯示空閒進程" aria-label="Permalink to “3.4 -i: 切換顯示空閒進程”">​</a></h3><p>這個選項設置top命令的上一次記住的<strong>相反的</strong>&#39;i&#39;狀態。</p><h3 id="_3-5-n-設置迭代數量" tabindex="-1">3.5 -n: 設置迭代數量 <a class="header-anchor" href="#_3-5-n-設置迭代數量" aria-label="Permalink to “3.5 -n: 設置迭代數量”">​</a></h3><p>用-n選項，你可以設置top退出前迭代的次數。</p><pre><code>$ top -n 3 
</code></pre><p>將會在刷新輸出3次後退出。</p><h3 id="_3-6-p-監控特定的pid" tabindex="-1">3.6 -p: 監控特定的PID <a class="header-anchor" href="#_3-6-p-監控特定的pid" aria-label="Permalink to “3.6 -p: 監控特定的PID”">​</a></h3><p>你可以用-p選項監控指定的PID。PID的值為0將被作為top命令自身的PID。</p><h3 id="_3-7-u-或-u-用户名-或者-uid" tabindex="-1">3.7 -u 或 -U: 用户名 或者 UID <a class="header-anchor" href="#_3-7-u-或-u-用户名-或者-uid" aria-label="Permalink to “3.7 -u 或 -U: 用户名 或者 UID”">​</a></h3><p>可以用這些選項瀏覽特定用户的進程。用户名或者UID可以在選項中指定。-p、-u和-U選項是互斥的，同時只可以使用這其中一個選項。當你試圖組合使用這些選項時，你會得到一個錯誤:</p><pre><code>$ top -p 28453 -u raghu
top: conflicting process selections (U/p/u) 
</code></pre><hr>`,141)),l("p",null,[a[1]||(a[1]=p("via: ",-1)),t(e,{href:"http://linoxide.com/linux-command/linux-top-command-examples-screenshots/"},{default:i(()=>[...a[0]||(a[0]=[p("http://linoxide.com/linux-command/linux-top-command-examples-screenshots/",-1)])]),_:1})]),l("p",null,[a[4]||(a[4]=p("譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:i(()=>[...a[2]||(a[2]=[p("geekpi",-1)])]),_:1}),a[5]||(a[5]=p(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[3]||(a[3]=[p("wxy",-1)])]),_:1})]),l("p",null,[a[8]||(a[8]=p("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[6]||(a[6]=[p("LCTT",-1)])]),_:1}),a[9]||(a[9]=p(" 原創翻譯，",-1)),t(e,{href:"http://linux.cn/"},{default:i(()=>[...a[7]||(a[7]=[p("Linux中國",-1)])]),_:1}),a[10]||(a[10]=p(" 榮譽推出",-1))])])}const k=o(h,[["render",c]]);export{f as __pageData,k as default};
